  const count=people.reduce((n,a)=>n+(a.members?.length||1),0),npcs=people.filter(a=>!a.isPC);
  if(count<=4||npcs.length<=1){out.push(...people);continue;}
  const members=npcs.flatMap(a=>a.members?.length?a.members:[a.name]);
  const summary=npcs.map(a=>[a.name,a.activity,a.observation,a.summary].filter(Boolean).join(' â€” ')).join('\n');
